     * seam consume (from OptimizerSettings; plain values keep the core
     * Qt-free).*/
    struct ProgressBudgets {
        int trunk_budget = 0;
        int branch_budget = 0;
        int number_branches = 0;
        bool enable_branch = false;
        int leaf_budget = 0;
        bool enable_leaf = false;
    };

