     * (one-shot). The shell applies it to the storage (snapshotting first
     * for the M10a restore) and maps the scene write. `applied == false`
     * means no seed or a stale one (dropped silently).*/
    struct AppliedSeed {
        bool applied = false;
        Point6D pose;
        int frame = -1;
        int model = -1;
    };

